<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Facades\Config;
class Event extends Model{protected $fillable=['app_slug','production_id','title','description','image','address','start_date','end_date','venue','uf','establishment_type','slug','city','state','country','location','cep','latitude','longitude','is_featured','is_published','is_approved','is_cancelled','max_attendees','remaining_tickets','extra_info','agenda','menu','additional_info','facebook_url','twitter_url','instagram_url','youtube_url','contact_email','contact_phone','website','registration_link','organizer_name','organizer_email','organizer_phone','organizer_description','speaker_list','sponsor_list','partners','reviews','rating','is_private','requires_approval','approval_message','segments','establishment_name'];protected $casts=['start_date'=>'datetime','end_date'=>'datetime','is_featured'=>'boolean','is_published'=>'boolean','is_approved'=>'boolean','is_cancelled'=>'boolean','is_private'=>'boolean','requires_approval'=>'boolean','extra_info'=>'array','agenda'=>'array','menu'=>'array','additional_info'=>'array','speaker_list'=>'array','sponsor_list'=>'array','partners'=>'array','reviews'=>'array','segments'=>'array','rating'=>'decimal:2','latitude'=>'decimal:7','longitude'=>'decimal:7','max_attendees'=>'integer','remaining_tickets'=>'integer'];public function production(){return $this->belongsTo(Production::class);}public function tickets(){return $this->hasMany(Ticket::class);}public function interactions(){return $this->hasMany(Interaction::class,'entity_id')->where('entity_type','event');}public function getSegmentsnNamesAttribute(){$a=is_array($this->segments)?$this->segments:[];if($a===[])return'<i>Nenhum segmento atribuído</i>';$n=[];$s=Config::get('segments',[]);foreach($a as $k)if(isset($s[$k]['name']))$n[]=$s[$k]['name'];return implode(' | ',$n);}}
